scene.onOverlapTile(SpriteKind.Player, assets.tile`myTile227`, function (sprite, location) {
    checkpoint = 2
    level = 2
    if (passed_2 == 0) {
        blockSettings.writeNumber("save", 3)
        if (life < 5) {
            life += 1
            effects.hearts.startScreenEffect(200)
        }
        effects.confetti.startScreenEffect(200)
    }
    passed_2 = 1
})
