scene.onOverlapTile(SpriteKind.Player, assets.tile`myTile66`, function (sprite, location) {
    checkpoint = 1
    if (passed == 0) {
        blockSettings.writeNumber("save", 2)
        if (life < 5) {
            life += 1
            effects.hearts.startScreenEffect(200)
        }
        effects.confetti.startScreenEffect(200)
    }
    passed = 1
})
